'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { resolve } = require('./src');
const { parse, compare, satisfies, compileRange } = require('./src/semver');

test('version ordering is numeric in every component', () => {
  for (const [older, newer] of [
    ['9.0.0', '10.0.0'],
    ['1.9.0', '1.10.0'],
    ['1.0.9', '1.0.10'],
    ['9007199254740990.0.0', '9007199254740991.0.0'],
  ]) {
    assert.deepEqual(resolve({ a: { [older]: {}, [newer]: {} } }, { a: '*' }), { a: newer });
    assert.equal(compare(older, newer), -1);
    assert.equal(compare(newer, older), 1);
  }
});

test('first-found selection follows root FIFO order, not global version maximization', () => {
  const registry = {
    a: { '2.0.0': { b: '1.0.0' }, '1.0.0': { b: '*' } },
    b: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*', b: '*' }), { a: '2.0.0', b: '1.0.0' });
  assert.deepEqual(resolve(registry, { b: '*', a: '*' }), { b: '2.0.0', a: '1.0.0' });
});

test('dependency FIFO order and immediate discovery constraints determine the first solution', () => {
  const registry = {
    entry: { '1.0.0': { a: '*', b: '*' } },
    a: { '2.0.0': { shared: '1.0.0' }, '1.0.0': { shared: '*' } },
    b: { '2.0.0': { shared: '2.0.0' }, '1.0.0': { shared: '1.0.0' } },
    shared: { '2.0.0': {}, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { entry: '*' }), {
    entry: '1.0.0', a: '2.0.0', b: '1.0.0', shared: '1.0.0',
  });
});

test('backtracking removes abandoned constraints but retains root constraints', () => {
  const registry = {
    a: { '2.0.0': { b: '2.0.0' }, '1.0.0': { b: '1.0.0' } },
    b: { '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
  assert.deepEqual(resolve(registry, { a: '*', b: '1.0.0' }), { a: '1.0.0', b: '1.0.0' });
  assert.equal(resolve(registry, { a: '*', b: '2.0.0' }), null);
});

test('immediate conflicts undo partially appended dependencies before retrying', () => {
  const registry = {
    b: { '2.0.0': {}, '1.0.0': {} },
    a: { '2.0.0': { abandoned: '*', b: '1.0.0' }, '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { b: '*', a: '*' }), { b: '2.0.0', a: '1.0.0' });
});

test('exhausted descendant choices remove their selected packages and discoveries', () => {
  const registry = {
    a: { '2.0.0': { b: '*' }, '1.0.0': { leaf: '*' } },
    b: { '2.0.0': { c: '2.0.0' }, '1.0.0': { c: '1.0.0' } },
    c: { '1.0.0': { missing: '*' } },
    leaf: { '1.0.0': {} },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', leaf: '1.0.0' });
});

test('cycles expand each selected package once and still enforce new constraints', () => {
  assert.deepEqual(resolve({ a: { '1.0.0': { a: '*' } } }, { a: '*' }), { a: '1.0.0' });
  const registry = {
    a: { '2.0.0': { b: '*' }, '1.0.0': { b: '*' } },
    b: { '1.0.0': { a: '1.0.0' } },
  };
  assert.deepEqual(resolve(registry, { a: '*' }), { a: '1.0.0', b: '1.0.0' });
  assert.equal(resolve(registry, { a: '2.0.0' }), null);
});

test('long chains and deep backtracking do not use recursive call-stack depth', () => {
  const registry = {};
  const expected = {};
  const count = 12000;
  for (let i = 0; i < count; i += 1) {
    const name = 'p' + i;
    registry[name] = { '1.0.0': i + 1 === count ? { p0: '1.0.0' } : { ['p' + (i + 1)]: '*' } };
    expected[name] = '1.0.0';
  }
  registry.p0['2.0.0'] = { p1: '*' };
  assert.deepEqual(resolve(registry, { p0: '*' }), expected);
});

test('discovered conflicts prune choices before enumerating a Cartesian product', () => {
  const registry = {};
  const root = {};
  const expected = {};
  for (let i = 0; i < 48; i += 1) {
    const name = 'p' + i;
    registry[name] = { '2.0.0': { [name]: '1.0.0' }, '1.0.0': {} };
    root[name] = '*';
    expected[name] = '1.0.0';
  }
  assert.deepEqual(resolve(registry, root), expected);
});

test('missing packages are unsatisfiable and empty roots have no reachable packages', () => {
  assert.equal(resolve({}, { missing: '*' }), null);
  assert.deepEqual(resolve({ unused: { '1.0.0': { missing: '*' } } }, {}), {});
});

test('all registry entries and ranges are validated eagerly', () => {
  for (const registry of [
    [],
    { unused: [] },
    { unused: { '1.0.0': [] } },
    { unused: { '01.0.0': {} } },
    { unused: { '9007199254740992.0.0': {} } },
    { unused: { '1.0.0': { missing: '^0.1.0 invalid' } } },
    { unused: { '1.0.0': { missing: '' } } },
  ]) assert.throws(() => resolve(registry, {}), TypeError);
  assert.throws(() => resolve({}, []), TypeError);
  assert.throws(() => resolve({}, { missing: null }), TypeError);
});

test('null-prototype maps, special keys, and frozen inputs preserve map semantics', () => {
  const registry = Object.create(null);
  const versions = Object.create(null);
  const deps = Object.create(null);
  deps.constructor = '*';
  versions['1.0.0'] = Object.freeze(deps);
  registry.__proto__ = Object.freeze(versions);
  registry.constructor = Object.freeze({ '1.0.0': Object.freeze({}) });
  Object.freeze(registry);
  const root = Object.create(null);
  root.__proto__ = '*';
  Object.freeze(root);
  const expected = { ['__proto__']: '1.0.0', constructor: '1.0.0' };
